window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["moe"]={"title":"混合专家 MoE：让每个 token 只激活少数前馈网络","subtitle":"从 top-k 路由与加权输出，到负载均衡、容量溢出、all-to-all、专家专化和推理批处理。","thesis":"MoE 用路由器为每个 token 选择少数专家，使总参数容量增长而单 token 激活参数增长较慢。它不是免费扩模：共享层仍稠密，且<b>路由质量、负载均衡、专家容量和跨设备通信</b>会决定真实质量与吞吐。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"4 个专家、6 个 token、每 token 选 2 个","rule":"平均负载为 12/4=3","steps":"E1: 5 / cap 3","interpretation":"E1 的 5 路中有 2 路必须处理溢出"}}],"formulas":[{"id":"moe-topk-routing","section":2,"formulaIndex":1,"symbols":[{"name":"x","meaning":"当前 token 经过共享层后的上下文向量","evidence":"x 是当前 token 的上下文向量"},{"name":"W","meaning":"把 token 表示映射为各专家分数的路由器权重","evidence":"Wᵣ 是路由器权重"},{"name":"g","meaning":"softmax 产生的所有专家路由概率向量","evidence":"概率向量 g"},{"name":"softmax","meaning":"把专家原始分数归一化为总和为一的概率","evidence":"softmax 输出每个专家的概率向量"},{"name":"k","meaning":"当前 token 要选择的专家数量","evidence":"k 是选几个专家"},{"name":"S","meaning":"概率最高的 k 个专家编号组成的集合","evidence":"S 是概率最高的 k 个专家编号集合"},{"name":"e","meaning":"被选集合中的某一个专家编号","evidence":"e 是其中一个专家"},{"name":"E","meaning":"某个专家前馈网络对 token 向量的输出","evidence":"Eₑ(x) 是专家 e 的 FFN 输出"},{"name":"y","meaning":"选中专家输出按路由权重合成的最终结果","evidence":"y 是加权合成的最终专家输出"}]},{"id":"moe-expert-capacity","section":3,"formulaIndex":1,"symbols":[{"name":"C","meaning":"单个专家在当前批次最多接收的路由数量","evidence":"C 是单个专家在这一批最多接收的路由数"},{"name":"ceil","meaning":"把计算结果向上取为最近整数","evidence":"ceil 表示向上取整"},{"name":"c","meaning":"在平均专家负载上增加容量余量的因子","evidence":"c 是容量因子"},{"name":"N","meaning":"当前用于路由的 token 总数","evidence":"N 是 token 数"},{"name":"k","meaning":"每个 token 选择的专家数量","evidence":"k 是每个 token 选择的专家数"},{"name":"E","meaning":"当前 MoE 层拥有的专家总数","evidence":"E 是专家总数"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"MoE 用多个可选 FFN 专家替换稠密 FFN，并为每个 token 只激活少数专家。","evidence":"替换为多个可选 FFN“专家”"},"problem":{"answer":"它让模型总参数容量增长，而单 token 的专家计算不必按总参数同比增长。","evidence":"总参数大，不等于每个 token 全部计算"},"inputOutput":{"answer":"输入是 token 上下文表示，输出是与原 FFN 相同维度的更新表示。","evidence":"输出仍是与原 FFN 相同维度的更新表示"},"mechanism":{"answer":"路由器选 top-k 专家执行，未选专家跳过，共享注意力等仍稠密计算。","evidence":"未选专家本次不计算"},"interpretation":{"answer":"总参数表示可选容量，激活参数更接近本 token 计算，但两者都不等于墙钟速度。","evidence":"不表示每个 token 调用了全部能力"},"boundary":{"answer":"总存储、加载、路由和通信仍增加，不能把稀疏专家当作免费稠密扩模。","evidence":"用参数容量与通信复杂度换取条件计算"}},{"section":2,"definition":{"answer":"top-k 路由为专家打分、选最高的 k 个，并加权合成它们的输出。","evidence":"路由器如何选择并组合专家"},"problem":{"answer":"它决定每个 token 使用哪些专家，以及多个专家结果怎样形成单一层输出。","evidence":"两个专家输出怎样合成"},"inputOutput":{"answer":"输入是 token 向量，输出是专家概率、选中集合和加权专家结果 y。","evidence":"y 是加权合成的最终专家输出"},"mechanism":{"answer":"W 路由打分经 softmax 得到 g，TopK 选 S，再在 S 内重归一化求和。","evidence":"只在已选集合 S 内重新归一化后的权重"},"interpretation":{"answer":"top-1 成本低但路径脆弱，top-2 增加冗余与表达也近似翻倍专家成本。","evidence":"top-2 增加冗余与表达"},"boundary":{"answer":"硬选择令未选专家无当前任务梯度，架构还可能混入共享专家，不能只看标签。","evidence":"未选专家收不到当前 token 的任务梯度"}},{"section":3,"definition":{"answer":"专家容量按平均路由负载乘容量因子并向上取整，限制单专家批次负载。","evidence":"容量按平均路由数乘安全系数分配"},"problem":{"answer":"它计算有限专家缓冲下热点专家会溢出多少，以及不同处理策略的代价。","evidence":"容量因子 1.0 时每专家能接多少"},"inputOutput":{"answer":"输入是 token、top-k、专家数和容量因子，输出容量及每个专家溢出量。","evidence":"4 个专家、6 个 token、每 token 选 2 个"},"mechanism":{"answer":"十二条路由除以四个专家得平均三条，CF 为一时容量就是三。","evidence":"平均负载为 12/4=3"},"interpretation":{"answer":"E1 收五条而容量三，说明两条必须丢弃、转路由或用更大容量。","evidence":"2 路必须处理溢出"},"boundary":{"answer":"提高容量减少丢弃却增加缓冲与最坏计算，重路由也会增加通信并改变语义。","evidence":"缓冲与最坏计算增"}},{"section":4,"definition":{"answer":"路由坍缩是少数专家越来越热门、其余专家因缺样本和梯度而饥饿的正反馈。","evidence":"专家几乎收不到样本和梯度"},"problem":{"answer":"它解释初期稍强的专家为何会持续吸收更多 token 并垄断训练信号。","evidence":"后续为什么可能越来越热门"},"inputOutput":{"answer":"输入是路由概率与实际分配，输出要兼顾任务质量、负载和溢出。","evidence":"输出要同时优化任务质量与专家负载"},"mechanism":{"answer":"辅助损失、探索噪声、z-loss 和容量约束分别抑制集中与数值过尖。","evidence":"约束路由 logits 不要无限变大"},"interpretation":{"answer":"专家熵和负载接近均匀只代表计算分散，不证明语义路由或群体质量。","evidence":"不能证明不同语言或群体获得同等质量"},"boundary":{"answer":"均衡过强会把本应去专业专家的 token 强行摊开并伤害任务质量。","evidence":"损害语义路由"}},{"section":5,"definition":{"answer":"专家并行以两次 all-to-all 把 token 发到专家设备并按原顺序返回。","evidence":"再 all-to-all 返回原顺序"},"problem":{"answer":"它让分散在不同 GPU 的专家处理各自 token，同时引入网络通信瓶颈。","evidence":"token 怎样到达被选专家再返回"},"inputOutput":{"answer":"输入是按目的专家分组的 token，输出是专家计算后恢复原序的表示。","evidence":"按目的专家打包 token"},"mechanism":{"answer":"设备按专家打包并全互换，专家计算后再全互换回发送设备。","evidence":"all-to-all 交换到持有专家的设备"},"interpretation":{"answer":"all-to-all 占比高或 GPU 等待表明路由偏斜、小消息或慢链路主导。","evidence":"不均匀消息使网络难以饱和"},"boundary":{"answer":"每 token FLOPs 下降不保证墙钟变快，MoE 依赖高速互连与足够批量。","evidence":"不保证墙钟延迟下降"}},{"section":6,"definition":{"answer":"生产推理的专家热点是实时流量让少数专家负载远高于训练时分布。","evidence":"训练与推理的热点分布可能不同"},"problem":{"answer":"它解释训练均衡的路由为何在小 batch 或主题突发的线上流量中爆满。","evidence":"生产为何仍可能某专家爆满"},"inputOutput":{"answer":"输入是逐 token 生产流量，输出是各层专家负载、熵、溢出和通信时间。","evidence":"推理监控每层/专家负载"},"mechanism":{"answer":"领域集中和逐 token 小批使路由更尖，同时所有专家权重仍需驻留或快速加载。","evidence":"batch 小、逐 token 生成会让路由分布更尖"},"interpretation":{"answer":"训练负载健康而线上热点高，说明数据分布和批处理条件发生了变化。","evidence":"对峰值主题压测"},"boundary":{"answer":"稀疏计算不等于稀疏存储，未激活专家通常仍要占显存或可快速访问。","evidence":"稀疏计算不等于稀疏存储"}},{"section":7,"definition":{"answer":"专家专化是假设某专家选择与特定能力存在稳定且可干预验证的功能关系。","evidence":"需要因果证据"},"problem":{"answer":"它避免因某专家常接代码 token 就拟人化地给它固定领域名称。","evidence":"就能叫“代码专家”吗"},"inputOutput":{"answer":"输入是路由日志与能力切片，输出是关联统计和干预后的能力变化。","evidence":"输出是关联统计及交换、屏蔽专家后的能力变化"},"mechanism":{"answer":"先测专家与切片关联，再交换或屏蔽专家，观察特定能力是否选择性下降。","evidence":"只有移除或交换某专家后代码能力选择性下降"},"interpretation":{"answer":"互信息只表示专家编号可由切片预测，干预后选择性下降才是更强功能证据。","evidence":"仍不能证明因果"},"boundary":{"answer":"共享注意力和跨层路由共同形成行为，单层专家标签不能解释整条回答或权限。","evidence":"多个层的路由共同形成行为"}},{"section":8,"definition":{"answer":"MoE、应用模型路由和多智能体都做选择，但决策粒度和候选对象不同。","evidence":"决策粒度有何不同"},"problem":{"answer":"它防止把模型内部 token 路由、请求级模型选择和子任务分工混成同一机制。","evidence":"MoE 与应用模型路由和多智能体不同"},"inputOutput":{"answer":"MoE 输入每层 token 并选 FFN，应用路由选完整服务，多智能体选角色或工具。","evidence":"每层每 token"},"mechanism":{"answer":"MoE 路由由内部参数学习，应用路由由可观测产品规则控制，多智能体编排子任务。","evidence":"应用路由可观测并由产品规则控制"},"interpretation":{"answer":"三者都叫路由不表示可交换，必须按错误发生的决策层归因。","evidence":"两者可叠加，评测需区分到底哪一层造成错误或延迟"},"boundary":{"answer":"当内部和应用路由叠加时，评测必须区分究竟哪一层造成错误或延迟。","evidence":"哪一层造成错误或延迟"}},{"section":9,"definition":{"answer":"MoE 验收联合比较容量、质量、路由稳定性和目标硬件系统效率。","evidence":"同时看容量、质量与系统效率"},"problem":{"answer":"它判断总参数大幅增加而激活 FLOPs 接近时，真实质量成本前沿是否改善。","evidence":"如何判断这次扩展值得"},"inputOutput":{"answer":"输入是 MoE 与同 FLOPs 稠密基线，输出质量、通信、负载、资源和恢复指标。","evidence":"输入是 MoE 与相同激活 FLOPs 的稠密基线"},"mechanism":{"answer":"同任务硬件下测质量与系统指标，再做专家消融、路由扰动和分布热点对比。","evidence":"做专家消融和路由扰动"},"interpretation":{"answer":"CV 越大表示负载相对偏斜更强，但 CV 低不证明语义或群体质量。","evidence":"越大表示相对偏斜越强"},"boundary":{"answer":"不能靠丢 token 或少数切片退化换吞吐，参数数字也必须同时报告 active 值。","evidence":"没有靠丢 token 或少数切片退化换吞吐"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>手算 top-k 路由与专家负载；区分总参数和激活参数；解释容量因子与辅助损失；诊断 all-to-all 和专家热点。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>总参数大，不等于每个 token 全部计算<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">一个有 8 个专家的模型，为什么 token “退款”可能只经过其中 2 个？</p><p><b>混合专家（MoE）</b>把 Transformer 中每个 token 都会经过的前馈网络 FFN，替换为多个可选 FFN“专家”。路由器读取当前 token 的上下文向量，只选分数最高的一个或两个专家执行；这就是 top-1 或 top-2。未选专家本次不计算，但注意力、嵌入、归一化和其他共享层仍为稠密计算。</p><p>输入是每个 token 的上下文表示，输出仍是与原 FFN 相同维度的更新表示。报告要区分 total parameters（模型存储的所有参数）、active parameters per token（该 token 实际经过的共享层和专家参数）与 FLOPs（执行的浮点运算次数）。总参数增加存储、加载和训练状态；激活参数更接近单 token 计算，但不包含路由与通信。</p><p>总参数大说明可供条件选择的容量多，不表示每个 token 调用了全部能力，也不保证墙钟速度更快。</p><div class=\"dd-note\"><b>MoE 的交换：</b>用参数容量与通信复杂度换取条件计算，不是把一万亿参数“免费”变成稠密一万亿能力。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>路由器如何选择并组合专家<span class=\"dd-badge math\">机制</span></h2><p class=\"dd-lead\">top-2 路由时两个专家输出怎样合成？</p><div class=\"dd-formula\" data-formula-id=\"moe-topk-routing\"><math display=\"block\" aria-label=\"路由概率 g 等于 softmax 对路由权重 W r 乘 token 向量 x；集合 S 是概率最高的 k 个专家；输出 y 等于集合 S 内各专家输出按重新归一化权重加权求和\"><mtable><mtr><mtd><mi>g</mi><mo>=</mo><mi>softmax</mi><mo>(</mo><msub><mi>W</mi><mi>r</mi></msub><mi>x</mi><mo>)</mo><mo>,</mo><mspace width=\"0.6em\"/><mi>S</mi><mo>=</mo><msub><mi>TopK</mi><mi>k</mi></msub><mo>(</mo><mi>g</mi><mo>)</mo></mtd></mtr><mtr><mtd><mi>y</mi><mo>=</mo><munder><mo>∑</mo><mrow><mi>e</mi><mo>∈</mo><mi>S</mi></mrow></munder><msub><mover><mi>g</mi><mo>^</mo></mover><mi>e</mi></msub><mo>·</mo><msub><mi>E</mi><mi>e</mi></msub><mo>(</mo><mi>x</mi><mo>)</mo></mtd></mtr></mtable></math></div><p class=\"dd-formula-note\"><code>x</code> 是当前 token 的上下文向量，<code>Wᵣ</code> 是路由器权重，softmax 输出每个专家的概率向量 <code>g</code>。<code>k</code> 是选几个专家，<code>S</code> 是概率最高的 k 个专家编号集合，<code>e</code> 是其中一个专家。<code>Eₑ(x)</code> 是专家 e 的 FFN 输出，<code>ĝₑ</code> 是只在已选集合 S 内重新归一化后的权重，<code>y</code> 是加权合成的最终专家输出。</p><p>top-1 计算和通信少但单一路径脆弱；top-2 增加冗余与表达，专家分支成本也近似翻倍。硬 top-k 是离散选择，未选专家收不到当前 token 的任务梯度，因此训练还需可微路由分数和均衡目标。</p><p>有的架构使用 shared expert 加 routed experts，使通用模式总有共享路径；细节因实现而异，不能只看“MoE”标签。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>运行示例：6 个 token 的 top-2 分发<span class=\"dd-badge math\">逐步演算</span></h2><p class=\"dd-lead\">4 个专家、6 个 token、每 token 选 2 个，容量因子 1.0 时每专家能接多少？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 710 270\" role=\"img\" aria-label=\"六个 token 通过 top-2 路由分发到四个专家并显示专家一过载\"><defs><marker id=\"mo1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"18\" y=\"86\" width=\"120\" height=\"96\" rx=\"9\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"78\" y=\"111\" text-anchor=\"middle\" class=\"svg-t\">6 token</text><text x=\"78\" y=\"134\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">退款/质量/订单</text><text x=\"78\" y=\"154\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">top-2 共 12 路由</text><path d=\"M138,134 L225,134\" stroke=\"#6b7484\" marker-end=\"url(#mo1)\"/><rect x=\"227\" y=\"86\" width=\"130\" height=\"96\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"292\" y=\"111\" text-anchor=\"middle\" class=\"svg-t\">路由器</text><text x=\"292\" y=\"134\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">E1:5 E2:3</text><text x=\"292\" y=\"154\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">E3:2 E4:2</text><path d=\"M357,134 L425,134\" stroke=\"#6b7484\" marker-end=\"url(#mo1)\"/><rect x=\"427\" y=\"35\" width=\"112\" height=\"48\" rx=\"7\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"483\" y=\"64\" text-anchor=\"middle\" class=\"svg-t\">E1: 5 / cap 3</text><rect x=\"427\" y=\"96\" width=\"112\" height=\"48\" rx=\"7\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"483\" y=\"125\" text-anchor=\"middle\" class=\"svg-t\">E2: 3 / cap 3</text><rect x=\"427\" y=\"157\" width=\"112\" height=\"48\" rx=\"7\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"483\" y=\"186\" text-anchor=\"middle\" class=\"svg-t\">E3: 2 / cap 3</text><rect x=\"427\" y=\"218\" width=\"112\" height=\"38\" rx=\"7\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"483\" y=\"242\" text-anchor=\"middle\" class=\"svg-t\">E4: 2 / cap 3</text><path d=\"M539,60 L606,60\" stroke=\"#c77b72\" marker-end=\"url(#mo1)\"/><rect x=\"608\" y=\"35\" width=\"86\" height=\"70\" rx=\"8\" fill=\"#21252d\" stroke=\"#c77b72\"/><text x=\"651\" y=\"59\" text-anchor=\"middle\" class=\"svg-t\">2 路溢出</text><text x=\"651\" y=\"80\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">丢弃/重路由</text><text x=\"651\" y=\"96\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">或增容量</text></svg><figcaption>图 1　平均负载为 12/4=3，因此 CF=1 的容量是 3；E1 的 5 路中有 2 路必须处理溢出。</figcaption></figure><div class=\"dd-formula\" data-formula-id=\"moe-expert-capacity\"><math display=\"block\" aria-label=\"每个专家容量等于向上取整容量因子 c 乘 token 数 N 乘每 token 专家数 k，再除以专家总数 E；示例结果为三\"><mrow><mi>C</mi><mo>=</mo><mi>ceil</mi><mo>(</mo><mfrac><mrow><mi>c</mi><mo>·</mo><mi>N</mi><mo>·</mo><mi>k</mi></mrow><mi>E</mi></mfrac><mo>)</mo><mo>=</mo><mi>ceil</mi><mo>(</mo><mfrac><mrow><mn>1</mn><mo>·</mo><mn>6</mn><mo>·</mo><mn>2</mn></mrow><mn>4</mn></mfrac><mo>)</mo><mo>=</mo><mn>3</mn></mrow></math></div><p class=\"dd-formula-note\"><code>C</code> 是单个专家在这一批最多接收的路由数，<code>ceil</code> 表示向上取整；<code>c</code> 是容量因子，<code>N</code> 是 token 数，<code>k</code> 是每个 token 选择的专家数，<code>E</code> 是专家总数。容量按平均路由数乘安全系数分配，因此热点专家仍可能溢出。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>策略</th><th>E1 溢出处理</th><th>质量</th><th>资源</th></tr></thead><tbody><tr><td>drop</td><td>丢 2 路</td><td>可能伤 token 表示</td><td>固定</td></tr><tr><td>second/backup</td><td>转其他专家</td><td>可恢复但语义变</td><td>通信增加</td></tr><tr><td>CF=2</td><td>容量 6</td><td>少丢弃</td><td>缓冲与最坏计算增</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>为什么路由会坍缩到少数专家<span class=\"dd-badge eng\">均衡</span></h2><p class=\"dd-lead\">如果 E1 早期稍强，后续为什么可能越来越热门？</p><p>更多 token 进入 E1→E1 获得更多任务梯度→表现更好→路由器更偏 E1，形成正反馈；其他专家几乎收不到样本和梯度，这叫专家饥饿。输入是路由概率和实际分配，输出要同时优化任务质量与专家负载。</p><p>辅助损失惩罚“少数专家概率或实际 token 占比过高”；路由噪声在训练时增加探索；z-loss 约束路由 logits 不要无限变大，以免 softmax 过尖和数值不稳；专家容量则限制单个专家最多接收多少路由。</p><p>均衡过强会把本应进入专业专家的 token 硬摊开，损害语义路由。应同时看任务 loss、专家熵、每专家 token、溢出率和质量，而非追求绝对均匀。负载均匀只是计算分配信号，不能证明不同语言或群体获得同等质量。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>all-to-all 让通信成为第一等成本<span class=\"dd-badge eng\">系统</span></h2><p class=\"dd-lead\">专家分散在 GPU 上，token 怎样到达被选专家再返回？</p><p>每个设备先按目的专家打包 token，all-to-all 交换到持有专家的设备，专家计算后再 all-to-all 返回原顺序。小批量、路由偏斜、跨节点链路和不均匀消息使网络难以饱和。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>瓶颈</th><th>表象</th><th>缓解</th></tr></thead><tbody><tr><td>专家热点</td><td>部分 GPU 等待/溢出</td><td>均衡、复制热门专家</td></tr><tr><td>跨节点带宽</td><td>all-to-all 占比高</td><td>拓扑感知放置/分组路由</td></tr><tr><td>小消息</td><td>延迟主导</td><td>增大 token batch/融合</td></tr><tr><td>长尾序列</td><td>动态批不均</td><td>容量和调度策略</td></tr></tbody></table></div><p>每 token FLOPs 下降不保证墙钟延迟下降；MoE 特别依赖高速互连与批量。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>训练与推理的热点分布可能不同<span class=\"dd-badge eng\">部署</span></h2><p class=\"dd-lead\">训练时均衡良好，生产为何仍可能某专家爆满？</p><p>训练混合语言/领域和 batch 大，推理流量可能突然集中某主题，且 batch 小、逐 token 生成会让路由分布更尖。专家并行还需将所有专家权重驻留或分层加载，总参数影响显存和启动。</p><p>推理监控每层/专家负载、路由熵、溢出、all-to-all 时间、批量和切片质量；对峰值主题压测。可做 expert parallel + tensor/data parallel 组合，但拓扑和故障恢复更复杂。</p><div class=\"dd-note warn\"><b>稀疏计算不等于稀疏存储。</b>　未激活专家当次不算，但通常仍需驻留或可快速访问。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>专家“专业名称”需要因果证据<span class=\"dd-badge eng\">解释</span></h2><p class=\"dd-lead\">某专家常接代码 token，就能叫“代码专家”吗？</p><p>路由可能按词频、位置、标点、语言或计算平衡分工；少量高频 token 例子容易拟人化。互信息在这里衡量“知道 token 属于某切片后，能多大程度预测专家编号”，它能发现统计关联，但仍不能证明因果。</p><p>验证输入是路由日志和能力切片，输出是关联统计及交换、屏蔽专家后的能力变化。只有移除或交换某专家后代码能力选择性下降，且其他混杂因素受控，才有更强的“代码相关功能”证据；同一专家在不同层含义也可能不同。</p><p>专家并非独立模块：共享注意力先混合上下文，多个层的路由共同形成行为。不能据某层专家标签推断整条回答为何生成，更不能把它当权限边界。路由日志显示“用了谁”，不等于证明“因为这个语义理由”。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>MoE 与应用模型路由和多智能体不同<span class=\"dd-badge intuition\">消歧</span></h2><p class=\"dd-lead\">它们都叫 routing，决策粒度有何不同？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>机制</th><th>选择单位</th><th>候选</th><th>主要目标</th></tr></thead><tbody><tr><td>MoE</td><td>每层每 token</td><td>模型内部 FFN 专家</td><td>参数容量/稀疏计算</td></tr><tr><td>模型路由</td><td>每请求/阶段</td><td>完整模型或服务</td><td>质量约束下成本</td></tr><tr><td>多智能体</td><td>子任务</td><td>角色/工具/上下文</td><td>分工、并行、隔离</td></tr></tbody></table></div><p>应用路由可观测并由产品规则控制；MoE 路由是模型内部学得参数。两者可叠加，评测需区分到底哪一层造成错误或延迟。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>评测要同时看容量、质量与系统效率<span class=\"dd-badge intuition\">评测</span></h2><p class=\"dd-lead\">总参数翻 8 倍、激活 FLOPs近似不变，如何判断这次扩展值得？</p><p>输入是 MoE 与相同激活 FLOPs 的稠密基线，以及同一任务、硬件、网络和批量。质量侧比较验证损失、任务、语言、安全、校准与稳定性；系统侧测 tokens/s、TTFT、TPOT、显存、all-to-all 占比、溢出、功耗和恢复。</p><p>专家负载 CV 是各专家负载标准差除以平均值，零表示完全均匀，越大表示相对偏斜越强；但 CV 低不等于语义路由或群体质量更好。做专家消融和路由扰动，检查少数专家故障是否让能力崩溃，并按训练与生产分布比较热点。</p><p>输出报告必须列出 total 与 active parameters、top-k、容量因子和并行拓扑，避免参数数字误导。只有目标网络和批量上质量—成本前沿可复现改善，且没有靠丢 token 或少数切片退化换吞吐，才算值得。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与概念依赖<span class=\"dd-badge intuition\">常见误区与学习路线</span></h2><p class=\"dd-lead\">MoE 是条件计算系统，瓶颈从矩阵乘转移到路由、容量和网络。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>每 token 使用全部总参数</td><td>只激活共享层与 top-k 专家</td></tr><tr><td>激活 FLOPs 少就一定快</td><td>all-to-all、热点和小批量可能主导</td></tr><tr><td>负载越均匀质量越好</td><td>过强均衡会破坏专业路由</td></tr><tr><td>专家编号天然对应领域</td><td>需统计与消融，分工可能按频率/位置</td></tr><tr><td>MoE 等于应用模型路由</td><td>前者每 token 选内部专家，后者每请求选完整模型</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸学习</th></tr></thead><tbody><tr><td>先修</td><td>Transformer FFN、softmax、稀疏计算</td></tr><tr><td><b>本页核心</b></td><td>top-k router、capacity factor、均衡损失、all-to-all</td></tr><tr><td>系统</td><td>分布式训练、推理优化、部署</td></tr><tr><td>对比</td><td>模型路由、多智能体、可解释性与缩放定律</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>token 表示进入路由器</li><li>选择 top-k 并分配容量</li><li>all-to-all 发送至专家</li><li>专家并行计算并加权返回</li><li>均衡/溢出控制热点</li><li>质量、通信、容量和切片联合验收</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>6 token、top-2、4专家、CF=1 的容量是多少？</li><li>E1 收到5路时发生什么？</li><li>总参数与激活参数差什么？</li><li>MoE 主要集合通信是什么？</li><li>为何不能直接给专家命名领域？</li><li>假设“混合专家 MoE：让每个 token 只激活少数前馈网络”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“混合专家 MoE：让每个 token 只激活少数前馈网络”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li><li>为什么不能只用一个平均分判断“混合专家 MoE：让每个 token 只激活少数前馈网络”已经可靠？应怎样按场景切片并设置失败边界？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>ceil(6×2/4)=3 路/专家。</li><li>2路需丢弃、重路由或提高容量。</li><li>总参数包含所有专家，激活参数只含当前 token 的共享层和 top-k 专家。</li><li>将 token 发往专家并返回的 all-to-all。</li><li>路由可能按其他统计分工，需干预和消融证据。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li><li>平均分会隐藏少数类别、极端输入、成本、延迟和安全失败。至少按难度、输入类型、长度或规模、风险等级及已知边界切片，同时报告质量、资源和失败率；高风险硬约束不能被其他切片的高分抵消。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1701.06538\" target=\"_blank\" rel=\"noopener\">Outrageously Large Neural Networks</a>：稀疏门控 MoE</li><li><a href=\"https://arxiv.org/abs/2006.16668\" target=\"_blank\" rel=\"noopener\">GShard</a>：大规模专家并行与容量</li><li><a href=\"https://arxiv.org/abs/2101.03961\" target=\"_blank\" rel=\"noopener\">Switch Transformers</a>：top-1 路由与均衡</li><li><a href=\"https://arxiv.org/abs/2202.08906\" target=\"_blank\" rel=\"noopener\">ST-MoE</a>：稳定训练与迁移</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
